    class MemRequest(ReadWriteKaitaiStruct):
        """52 (read), 47, or 44: 24-bit little-endian address, 16-bit little-endian length, 6 bytes in
        all. A read of `blockBase + 0xfff`, length 1, returns a 4 KB page's logical block id; the
        address 0xfff001 is the "no page" sentinel. 0x44 makes the stock loop call
        sdcard_data_block_read (formerly flash_program_data_block_write) with the address and (length < 0x200 ? 1 : (length >> 9) & 0xff)
        and reply like a read; never captured, purpose unknown.
        """
        def __init__(self, _io=None, _parent=None, _root=None):
            super(CpsSerial.MemRequest, self).__init__(_io)
            self._parent = _parent
            self._root = _root

        def _read(self):
            self.addr_lo = self._io.read_u1()
            self.addr_mid = self._io.read_u1()
            self.addr_hi = self._io.read_u1()
            self.length = self._io.read_u2le()
            self._dirty = False


        def _fetch_instances(self):
            pass


        def _write__seq(self, io=None):
            super(CpsSerial.MemRequest, self)._write__seq(io)
            self._io.write_u1(self.addr_lo)
            self._io.write_u1(self.addr_mid)
            self._io.write_u1(self.addr_hi)
            self._io.write_u2le(self.length)


        def _check(self):
            self._dirty = False

        @property
        def addr(self):
            """The 24-bit data-chip address."""
            if hasattr(self, '_m_addr'):
                return self._m_addr

            self._m_addr = (self.addr_lo | self.addr_mid << 8) | self.addr_hi << 16
            return getattr(self, '_m_addr', None)

        def _invalidate_addr(self):
            del self._m_addr
        @property
        def is_sentinel(self):
            """True for the "no physical page" sentinel address."""
            if hasattr(self, '_m_is_sentinel'):
                return self._m_is_sentinel

            self._m_is_sentinel = self.addr == 16773121
            return getattr(self, '_m_is_sentinel', None)

        def _invalidate_is_sentinel(self):
            del self._m_is_sentinel

