    class RadioSession(ReadWriteKaitaiStruct):
        """Radio-to-host stream of one OEM-order session. Assumes the info loop got only V-frames and
        0x47 reads (true of every CPS capture): its first 0x06 is then the PROGRAM ack.
        """
        def __init__(self, _io=None, _parent=None, _root=None):
            super(CpsSerial.RadioSession, self).__init__(_io)
            self._parent = _parent
            self._root = _root

        def _read(self):
            self.psearch_reply = CpsSerial.PsearchReply(self._io, self, self._root)
            self.psearch_reply._read()
            self.passsta_reply = CpsSerial.PassstaReply(self._io, self, self._root)
            self.passsta_reply._read()
            self.sysinfo_ack = self._io.read_bytes(1)
            if not self.sysinfo_ack == b"\x06":
                raise kaitaistruct.ValidationNotEqualError(b"\x06", self.sysinfo_ack, self._io, u"/types/radio_session/seq/2")
            self.info_replies = []
            i = 0
            while True:
                _t_info_replies = CpsSerial.InfoRadioFrame(self._io, self, self._root)
                try:
                    _t_info_replies._read()
                finally:
                    _ = _t_info_replies
                    self.info_replies.append(_)
                if _.code == CpsSerial.RadioCode.ack:
                    break
                i += 1
            self.mode_reply = self._io.read_bytes(8)
            if not self.mode_reply == b"\xFF\xFF\xFF\xFF\xFF\xFF\xFF\xFF":
                raise kaitaistruct.ValidationNotEqualError(b"\xFF\xFF\xFF\xFF\xFF\xFF\xFF\xFF", self.mode_reply, self._io, u"/types/radio_session/seq/4")
            self.confirm_ack = self._io.read_bytes(1)
            if not self.confirm_ack == b"\x06":
                raise kaitaistruct.ValidationNotEqualError(b"\x06", self.confirm_ack, self._io, u"/types/radio_session/seq/5")
            self.frames = []
            i = 0
            while not self._io.is_eof():
                _t_frames = CpsSerial.ProgrammingRadioFrame(self._io, self, self._root)
                try:
                    _t_frames._read()
                finally:
                    self.frames.append(_t_frames)
                i += 1

            self._dirty = False


        def _fetch_instances(self):
            pass
            self.psearch_reply._fetch_instances()
            self.passsta_reply._fetch_instances()
            for i in range(len(self.info_replies)):
                pass
                self.info_replies[i]._fetch_instances()

            for i in range(len(self.frames)):
                pass
                self.frames[i]._fetch_instances()



        def _write__seq(self, io=None):
            super(CpsSerial.RadioSession, self)._write__seq(io)
            self.psearch_reply._write__seq(self._io)
            self.passsta_reply._write__seq(self._io)
            self._io.write_bytes(self.sysinfo_ack)
            for i in range(len(self.info_replies)):
                pass
                self.info_replies[i]._write__seq(self._io)

            self._io.write_bytes(self.mode_reply)
            self._io.write_bytes(self.confirm_ack)
            for i in range(len(self.frames)):
                pass
                if self._io.is_eof():
                    raise kaitaistruct.ConsistencyError(u"frames", 0, self._io.size() - self._io.pos())
                self.frames[i]._write__seq(self._io)

            if not self._io.is_eof():
                raise kaitaistruct.ConsistencyError(u"frames", 0, self._io.size() - self._io.pos())


        def _check(self):
            if self.psearch_reply._root != self._root:
                raise kaitaistruct.ConsistencyError(u"psearch_reply", self._root, self.psearch_reply._root)
            if self.psearch_reply._parent != self:
                raise kaitaistruct.ConsistencyError(u"psearch_reply", self, self.psearch_reply._parent)
            if self.passsta_reply._root != self._root:
                raise kaitaistruct.ConsistencyError(u"passsta_reply", self._root, self.passsta_reply._root)
            if self.passsta_reply._parent != self:
                raise kaitaistruct.ConsistencyError(u"passsta_reply", self, self.passsta_reply._parent)
            if len(self.sysinfo_ack) != 1:
                raise kaitaistruct.ConsistencyError(u"sysinfo_ack", 1, len(self.sysinfo_ack))
            if not self.sysinfo_ack == b"\x06":
                raise kaitaistruct.ValidationNotEqualError(b"\x06", self.sysinfo_ack, None, u"/types/radio_session/seq/2")
            if len(self.info_replies) == 0:
                raise kaitaistruct.ConsistencyError(u"info_replies", 0, len(self.info_replies))
            for i in range(len(self.info_replies)):
                pass
                if self.info_replies[i]._root != self._root:
                    raise kaitaistruct.ConsistencyError(u"info_replies", self._root, self.info_replies[i]._root)
                if self.info_replies[i]._parent != self:
                    raise kaitaistruct.ConsistencyError(u"info_replies", self, self.info_replies[i]._parent)
                _ = self.info_replies[i]
                if (_.code == CpsSerial.RadioCode.ack) != (i == len(self.info_replies) - 1):
                    raise kaitaistruct.ConsistencyError(u"info_replies", i == len(self.info_replies) - 1, _.code == CpsSerial.RadioCode.ack)

            if len(self.mode_reply) != 8:
                raise kaitaistruct.ConsistencyError(u"mode_reply", 8, len(self.mode_reply))
            if not self.mode_reply == b"\xFF\xFF\xFF\xFF\xFF\xFF\xFF\xFF":
                raise kaitaistruct.ValidationNotEqualError(b"\xFF\xFF\xFF\xFF\xFF\xFF\xFF\xFF", self.mode_reply, None, u"/types/radio_session/seq/4")
            if len(self.confirm_ack) != 1:
                raise kaitaistruct.ConsistencyError(u"confirm_ack", 1, len(self.confirm_ack))
            if not self.confirm_ack == b"\x06":
                raise kaitaistruct.ValidationNotEqualError(b"\x06", self.confirm_ack, None, u"/types/radio_session/seq/5")
            for i in range(len(self.frames)):
                pass
                if self.frames[i]._root != self._root:
                    raise kaitaistruct.ConsistencyError(u"frames", self._root, self.frames[i]._root)
                if self.frames[i]._parent != self:
                    raise kaitaistruct.ConsistencyError(u"frames", self, self.frames[i]._parent)

            self._dirty = False


    class RangePayload(ReadWriteKaitaiStruct):
        """start and end address of a data-chip region, both u32 LE; end is the region's last byte."""
        def __init__(self, _io=None, _parent=None, _root=None):
            super(CpsSerial.RangePayload, self).__init__(_io)
            self._parent = _parent
            self._root = _root

        def _read(self):
            self.start = self._io.read_u4le()
            self.end = self._io.read_u4le()
            self.extra = self._io.read_bytes_full()
            self._dirty = False


        def _fetch_instances(self):
            pass


        def _write__seq(self, io=None):
            super(CpsSerial.RangePayload, self)._write__seq(io)
            self._io.write_u4le(self.start)
            self._io.write_u4le(self.end)
            self._io.write_bytes(self.extra)
            if not self._io.is_eof():
                raise kaitaistruct.ConsistencyError(u"extra", 0, self._io.size() - self._io.pos())


        def _check(self):
            self._dirty = False

        @property
        def size(self):
            """Region size in bytes."""
            if hasattr(self, '_m_size'):
                return self._m_size

            self._m_size = (self.end - self.start) + 1
            return getattr(self, '_m_size', None)

        def _invalidate_size(self):
            del self._m_size

    class VframeRequest(ReadWriteKaitaiStruct):
        """56 a b c <id>, always 5 bytes. For id 0x0d the stock parser reads a 16-bit big-endian table
        offset from a:b and the reply length from c (so `56 00 00 40 0D` returns 64 bytes and
        `56 00 00 00 0D` none). For every other id a, b and c must be 0 or the loop returns.
        """
        def __init__(self, _io=None, _parent=None, _root=None):
            super(CpsSerial.VframeRequest, self).__init__(_io)
            self._parent = _parent
            self._root = _root

        def _read(self):
            self.arg_a = self._io.read_u1()
            self.arg_b = self._io.read_u1()
            self.arg_c = self._io.read_u1()
            self.sub_id = KaitaiStream.resolve_enum(CpsSerial.VframeId, self._io.read_u1())
            self._dirty = False


        def _fetch_instances(self):
            pass


        def _write__seq(self, io=None):
            super(CpsSerial.VframeRequest, self)._write__seq(io)
            self._io.write_u1(self.arg_a)
            self._io.write_u1(self.arg_b)
            self._io.write_u1(self.arg_c)
            self._io.write_u1(int(self.sub_id))


        def _check(self):
            self._dirty = False

        @property
        def table_offset(self):
            """Offset into the stock 0x0d table (sub_id 0x0d only)."""
            if hasattr(self, '_m_table_offset'):
                return self._m_table_offset

            self._m_table_offset = self.arg_a * 256 + self.arg_b
            return getattr(self, '_m_table_offset', None)

        def _invalidate_table_offset(self):
            del self._m_table_offset

